    const tenant = await createTenant("authority-up", "free");
    const { actors, org } = tenant;

    // Free: two projects (one exists), three seats (four members exist), no CSV.
    await projectService.createProject(actors.owner, projectInput(org.id));
    await expect(
      projectService.createProject(actors.owner, projectInput(org.id)),
    ).rejects.toThrow(/Plan free/);
    await expect(
      invitationService.inviteMember(actors.admin, {
        orgId: org.id,
        email: "one@authority-up.test",
        role: "member",
      }),
    ).rejects.toThrow(/Plan free includes 3 seats/);
    await expect(
      activityService.exportActivity(actors.admin, { orgId: org.id, format: "csv" } as never),
    ).rejects.toThrow(/not included/);

    await move(tenant, "growth");

    await expect(
      projectService.createProject(actors.owner, projectInput(org.id)),
    ).resolves.toBeDefined();
    await expect(
      invitationService.inviteMember(actors.admin, {
        orgId: org.id,
        email: "two@authority-up.test",
        role: "member",
      }),
    ).resolves.toBeDefined();
    await expect(
      activityService.exportActivity(actors.admin, { orgId: org.id, format: "csv" } as never),
    ).resolves.toEqual(expect.any(String));

    expect((await orgRepo.findOrgById(org.id))?.plan).toBe("growth");
    expect((await orgRepo.findOrgBySlug(org.slug))?.plan).toBe("growth");
    expect((await orgService.listOrganizationsForUser(tenant.userIds.owner)).map((o) => o.plan)).toEqual([
      "growth",
    ]);
    expect((await billingService.checkLimit(org.id, "projects", 0)).plan).toBe("growth");
  });

  it("applies a downgrade to feature-gated endpoints", async () => {
    const tenant = await createTenant("authority-down", "growth");
    const { actors, org } = tenant;
    const input = { orgId: org.id, url: "https://hooks.example.com/a", eventTypes: ["issue.created" as const] };

    await expect(webhookService.createWebhook(actors.admin, input)).resolves.toBeDefined();

    await move(tenant, "starter");

    await expect(webhookService.createWebhook(actors.admin, input)).rejects.toThrow(
      /not included in this plan/,
    );
    expect((await orgRepo.findOrgById(org.id))?.plan).toBe("starter");
  });

  it("follows the subscription when the workspace record already disagrees", async () => {
    const upgraded = await createTenant("authority-drift-up", "growth");
    setOrgColumn(upgraded.org.id, "free");
    expect((await orgRepo.findOrgById(upgraded.org.id))?.plan).toBe("growth");
    await projectService.createProject(upgraded.actors.owner, projectInput(upgraded.org.id));
    await projectService.createProject(upgraded.actors.owner, projectInput(upgraded.org.id));

    const downgraded = await createTenant("authority-drift-down", "free");
    setOrgColumn(downgraded.org.id, "enterprise");
    expect((await orgRepo.findOrgById(downgraded.org.id))?.plan).toBe("free");
    await projectService.createProject(downgraded.actors.owner, projectInput(downgraded.org.id));
    await expect(
      projectService.createProject(downgraded.actors.owner, projectInput(downgraded.org.id)),
    ).rejects.toThrow(/Plan free/);
  });

  it("keeps using the workspace's own plan when it has no subscription", async () => {
    const tenant = await createTenant("authority-no-sub", "growth");
    getDb().delete(subscriptions).where(eq(subscriptions.orgId, tenant.org.id)).run();
    setOrgColumn(tenant.org.id, "starter");

    expect((await orgRepo.findOrgById(tenant.org.id))?.plan).toBe("starter");
    expect((await billingService.checkLimit(tenant.org.id, "projects", 0)).plan).toBe("starter");
    expect(await burst(tenant.org.id, "comment:create", 61)).toBe(61);
  });

  it("leaves other workspaces alone", async () => {
    const first = await createTenant("authority-iso-a", "free");
    const second = await createTenant("authority-iso-b", "free");

    await move(first, "growth");

    expect((await orgRepo.findOrgById(second.org.id))?.plan).toBe("free");
    expect((await subscriptionRepo.findSubscription(second.org.id))?.plan).toBe("free");
  });

  it("changes nothing when a plan change is refused", async () => {
    const tenant = await createTenant("authority-refused", "growth");
    await usageRepo.incrementUsage(tenant.org.id, { seatsUsed: 5 });

    await expect(move(tenant, "free")).rejects.toThrow(/seats exceeds/);

    expect((await orgRepo.findOrgById(tenant.org.id))?.plan).toBe("growth");
    expect((await subscriptionRepo.findSubscription(tenant.org.id))?.plan).toBe("growth");
  });
});

describe("burst limits follow the plan", () => {
  it("resizes the buckets as soon as the plan changes", async () => {
    const tenant = await createTenant("authority-burst", "free");
    const id = tenant.org.id;

    // Free: capacity 60.
    expect(await burst(id, "comment:create", 100)).toBe(60);

    await move(tenant, "growth");
    expect(await burst(id, "comment:create", 500)).toBe(500);
    expect((await consumeRateLimit(id, "search:query")).remaining).toBeGreaterThan(120);
    expect((await consumeRateLimit(id, "member:invite")).remaining).toBeGreaterThan(20);

    await move(tenant, "free");
    expect(await burst(id, "comment:create", 1_000)).toBeLessThanOrEqual(60);
  });

  it("uses the subscription's plan when the workspace record disagrees", async () => {
    const tenant = await createTenant("authority-burst-drift", "growth");
    setOrgColumn(tenant.org.id, "free");

    expect(await burst(tenant.org.id, "comment:create", 200)).toBe(200);
  });
});

describe("trial expiry", () => {
  const NOW = () => new Date(Date.now() + 30 * 24 * 60 * 60 * 1000);

  it("moves a trial that ran out to Free everywhere, once", async () => {
    const tenant = await createTenant("authority-trial", "growth");
    const other = await createTenant("authority-trial-other", "growth");
    const { actors, org } = tenant;

    const first = await runTrialExpiryJob(NOW());
    expect(first.processed).toBeGreaterThanOrEqual(2);

    expect((await subscriptionRepo.findSubscription(org.id))?.plan).toBe("free");
    expect((await orgRepo.findOrgById(org.id))?.plan).toBe("free");
    await projectService.createProject(actors.owner, projectInput(org.id));
    await expect(
      projectService.createProject(actors.owner, projectInput(org.id)),
    ).rejects.toThrow(/Plan free/);
    await expect(
      webhookService.createWebhook(actors.admin, {
        orgId: org.id,
        url: "https://hooks.example.com/b",
        eventTypes: ["issue.created"],
      }),
    ).rejects.toThrow(/not included/);

    const second = await runTrialExpiryJob(NOW());
    expect(second.processed).toBe(0);
    expect((await orgRepo.findOrgById(other.org.id))?.plan).toBe("free");
  });

  it("leaves a workspace that chose a paid plan during its trial on that plan", async () => {
    const tenant = await createTenant("authority-trial-chose", "starter");
    await move(tenant, "growth");

    await runTrialExpiryJob(NOW());

    const subscription = await subscriptionRepo.findSubscription(tenant.org.id);
    expect(subscription?.plan).toBe("growth");
    expect(subscription?.status).toBe("active");
    expect((await orgRepo.findOrgById(tenant.org.id))?.plan).toBe("growth");
  });

  it("leaves a trial that outgrew the Free limits on its plan", async () => {
    const tenant = await createTenant("authority-trial-big", "growth");
    await usageRepo.incrementUsage(tenant.org.id, { seatsUsed: 5 });

    const result = await runTrialExpiryJob(NOW());

    expect(result.failed).toBeGreaterThanOrEqual(1);
    expect((await orgRepo.findOrgById(tenant.org.id))?.plan).toBe("growth");
  });

  it("does not touch a trial whose window has not ended", async () => {
    const tenant = await createTenant("authority-trial-live", "growth");
    setSubscription(tenant.org.id, { status: "trialing" });

    await runTrialExpiryJob(new Date());

    expect((await orgRepo.findOrgById(tenant.org.id))?.plan).toBe("growth");
  });
});

