let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

beforeEach(() => {
  resetRateLimits();
});

let counter = 0;

function projectInput(orgId: OrgId): CreateProjectInput {
  counter += 1;
  return {
    orgId,
    name: `Project ${counter}`,
    slug: `project-${counter}`,
    key: `PR${counter}`,
    description: null,
    visibility: "org",
    leadId: null,
    color: "#6366f1",
    targetDate: null,
  };
}

async function move(tenant: Tenant, plan: PlanId): Promise<void> {
  await billingService.changePlan(tenant.actors.owner, {
    orgId: tenant.org.id,
    plan,
    interval: "monthly",
  });
}

function setOrgColumn(orgId: OrgId, plan: PlanId): void {
  getDb().update(organizations).set({ plan }).where(eq(organizations.id, orgId)).run();
}

function setSubscription(orgId: OrgId, patch: Partial<typeof subscriptions.$inferInsert>): void {
  getDb().update(subscriptions).set(patch).where(eq(subscriptions.orgId, orgId)).run();
}

async function burst(orgId: OrgId, bucket: string, attempts: number): Promise<number> {
  let allowed = 0;
  for (let i = 0; i < attempts; i += 1) {
    if ((await consumeRateLimit(orgId, bucket)).allowed) allowed += 1;
  }
  return allowed;
}

